fn rotate(a: &[i32], offset: usize) -> Vec<i32> {
    let n = a.len();
    if n == 0 {
        return Vec::new();
    }

    // Effective rotation offset within [0, n)
    let k = offset % n;

    // Build the rotated array by concatenating the two slices
    let mut result = Vec::with_capacity(n);
    result.extend_from_slice(&a[k..]);
    result.extend_from_slice(&a[..k]);
    result
}

